"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["4262"],{2253(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>u,frontMatter:()=>r,contentTitle:()=>d,toc:()=>l,assets:()=>h});var s=JSON.parse('{"id":"m9-capstone-ai-assistant/lesson","title":"Lesson: Capstone \u2014 Your AI Assistant, End to End","description":"What happens when five separate things become one thing?","source":"@site/docs/m9-capstone-ai-assistant/lesson.md","sourceDirName":"m9-capstone-ai-assistant","slug":"/m9-capstone-ai-assistant/lesson","permalink":"/aiml-foundations-site/docs/m9-capstone-ai-assistant/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: Capstone \u2014 Your AI Assistant, End to End"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/aiml-foundations-site/docs/m8-mlops-llmops-agenticops/deep-dive"},"next":{"title":"Lab: Capstone \u2014 Your AI Assistant, End to End","permalink":"/aiml-foundations-site/docs/m9-capstone-ai-assistant/lab"}}'),o=t(4848),a=t(8453),i=t(7684);let r={sidebar_position:1,title:"Lesson: Capstone \u2014 Your AI Assistant, End to End"},d="Capstone \u2014 Your AI Assistant, End to End",h={},l=[{value:"What happens when five separate things become one thing?",id:"what-happens-when-five-separate-things-become-one-thing",level:2},{value:"Module slides",id:"module-slides",level:2},{value:"The capstone brief: what you&#39;re building",id:"the-capstone-brief-what-youre-building",level:2},{value:"The architecture, end to end",id:"the-architecture-end-to-end",level:2},{value:"The project spine, converged \u2014 and what didn&#39;t converge",id:"the-project-spine-converged--and-what-didnt-converge",level:2},{value:"Three tools, one assistant",id:"three-tools-one-assistant",level:2},{value:"Honesty over confidence",id:"honesty-over-confidence",level:2},{value:"What&#39;s next",id:"whats-next",level:2}];function c(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",mermaid:"mermaid",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"capstone--your-ai-assistant-end-to-end",children:"Capstone \u2014 Your AI Assistant, End to End"})}),"\n",(0,o.jsx)(n.h2,{id:"what-happens-when-five-separate-things-become-one-thing",children:"What happens when five separate things become one thing?"}),"\n",(0,o.jsx)(n.p,{children:"You've built five separate pieces across this course. A three-line call to an LLM in\nModule 1 and Module 5. An agent that reasons over tools in Module 6. A RAG pipeline that\nanswers from your own PDF, also in Module 6. A model served behind a real API in Module 7\nand Module 8. Each one worked on its own, in its own lab, torn down when you were done."}),"\n",(0,o.jsx)(n.p,{children:"Today you stop tearing them down. You wire the LLM call, the agent loop, and the RAG\npipeline into one assistant, and you serve that assistant behind the same kind of API\nModule 7 taught you to build. By the end of this lesson you can describe that assistant's\nfull architecture end to end, and you know exactly which of your earlier labs each piece\nof it comes from \u2014 nothing here is new machinery, only new wiring."}),"\n",(0,o.jsx)(n.h2,{id:"module-slides",children:"Module slides"}),"\n",(0,o.jsx)(n.p,{children:"Walk this short whiteboard deck for the big picture before the hands-on build, or open it\nfullscreen."}),"\n",(0,o.jsx)(i.A,{src:"decks/m9-capstone-ai-assistant.html",title:"M9 \u2014 Capstone: Your AI Assistant"}),"\n",(0,o.jsx)(n.h2,{id:"the-capstone-brief-what-youre-building",children:"The capstone brief: what you're building"}),"\n",(0,o.jsx)(n.p,{children:"Here's the plain description, before any code: a document-savvy AI assistant. You ask it a\nquestion. If the question needs something current, it searches the web. If it needs a\ncalculation, it does the math instead of guessing. If it needs something from a PDF you\ngave it, it looks the answer up in that document instead of making one up. And it does all\nof this behind a single API endpoint, so anything \u2014 a script, a curl command, a real\nclient \u2014 can ask it a question the same way you'd ask a colleague."}),"\n",(0,o.jsx)(n.p,{children:"That's the whole brief. Nothing about it is a new idea. It's Module 6's agent loop, with a\nthird tool added, standing behind Module 7's serving pattern."}),"\n",(0,o.jsx)(n.h2,{id:"the-architecture-end-to-end",children:"The architecture, end to end"}),"\n",(0,o.jsx)(n.p,{children:"This is the diagram this whole course has been building toward \u2014 every earlier module is\none box in it."}),"\n",(0,o.jsx)(n.mermaid,{value:'graph TD\n    CLIENT["Client<br/>(curl, script, browser)"] --\x3e|"POST /ask"| API["FastAPI endpoint<br/>(Module 7/8 pattern)"]\n    API --\x3e LOOP["Agent loop<br/>(Module 6)"]\n    LOOP --\x3e|"reason"| LLM["LLM<br/>(Module 1/5)"]\n    LLM --\x3e|"needs a fact or a number"| TOOLS["Pick a tool"]\n    TOOLS --\x3e SEARCH["web_search"]\n    TOOLS --\x3e CALC["calculator"]\n    TOOLS --\x3e RAG["retrieve_document<br/>(Module 6 RAG)"]\n    SEARCH --\x3e LOOP\n    CALC --\x3e LOOP\n    RAG --\x3e LOOP\n    LOOP --\x3e|"has enough to answer"| RESPONSE["Response"]\n    RESPONSE --\x3e CLIENT'}),"\n",(0,o.jsxs)(n.p,{children:["Read it left to right. A request lands on the ",(0,o.jsx)(n.code,{children:"/ask"})," endpoint \u2014 the same shape as Module\n7's ",(0,o.jsx)(n.code,{children:"/predict"}),", only asking a question instead of handing over a set of features. The\nendpoint hands the question to the agent loop from Module 6, unchanged. The loop reasons,\nand if it needs something it doesn't already know, it picks one of three tools: search the\nweb, do a calculation, or look inside the PDF you gave it. The tool's result goes back into\nthe loop, the model reasons again, and once it has enough, it answers \u2014 and that answer is\nwhat the endpoint sends back to whoever asked."]}),"\n",(0,o.jsx)(n.h2,{id:"the-project-spine-converged--and-what-didnt-converge",children:"The project spine, converged \u2014 and what didn't converge"}),"\n",(0,o.jsx)(n.p,{children:"It's worth being precise about what \"capstone\" means here, because not everything you\nbuilt folds into this one assistant. Module 3's regression model predicted a house price.\nModule 4's neural net classified a handwritten digit. Both were real, standalone labs, and\nneither one is part of a document-savvy assistant \u2014 a predictor and a classifier don't\nbelong inside a chat loop, and forcing them in would be a fake connection, not a real one."}),"\n",(0,o.jsx)(n.p,{children:"What does converge here is the generative and agentic thread: the LLM call from Module 1\nand Module 5, the agent loop and RAG pipeline from Module 6, and the serving pattern from\nModule 7 and Module 8. Four separate labs, one assistant. That's an honest, satisfying\nconvergence on its own \u2014 you don't need the whole course to fold into one artifact for\ntoday to be the payoff module."}),"\n",(0,o.jsx)(n.h2,{id:"three-tools-one-assistant",children:"Three tools, one assistant"}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Analogy:"})," think about a good helpdesk. Ask it something written in the company manual,\nand it opens the manual and reads you the relevant page \u2014 it doesn't recite the answer from\nmemory, because memory drifts and the manual doesn't. Ask it something the manual can't\npossibly cover, like today's exchange rate, and it looks it up instead of guessing. Ask it\nto work out a number, and it reaches for a calculator instead of doing arithmetic in its\nhead under pressure. A good helpdesk doesn't try to answer everything the same way \u2014 it\npicks the right method for the question in front of it."]}),"\n",(0,o.jsxs)(n.p,{children:["That's your assistant's three tools. ",(0,o.jsx)(n.code,{children:"calculator"})," is the arithmetic you already trust from\nModule 6, unchanged. ",(0,o.jsx)(n.code,{children:"web_search"})," is the same free, no-key web search from Module 6,\nunchanged. The new one is ",(0,o.jsx)(n.code,{children:"retrieve_document"})," \u2014 Module 6's bonus RAG pipeline, which used\nto be a script you ran by hand after deciding the question was about the PDF, now turned\ninto a tool the agent decides to call for itself. The agent loop doesn't change at all to\nsupport this. It already knew how to pick a tool from a list and read back whatever came\nout. Handing it a third option is exactly as much new code as handing it a second one was\nin Module 6 \u2014 one more schema, one more Python function, nothing structural."]}),"\n",(0,o.jsx)(n.h2,{id:"honesty-over-confidence",children:"Honesty over confidence"}),"\n",(0,o.jsxs)(n.p,{children:["Here's where today's lab deliberately tries to break the assistant, not just show it\nworking. Module 5 taught you why LLMs hallucinate: a model always produces its most likely\nnext words, whether or not those words are actually true. Module 6 taught you prompt\ninjection: text a tool returns can carry instructions the model shouldn't trust. Today's\nassistant sits at the intersection of both risks, because ",(0,o.jsx)(n.code,{children:"retrieve_document"})," hands the\nmodel real text pulled from a document it didn't write."]}),"\n",(0,o.jsx)(n.p,{children:"The defense you'll test in the lab is a plain instruction in the system prompt: if the\nretrieved passages don't answer the question, say so, instead of falling back on a\nplausible-sounding guess. You'll ask your assistant something the PDF genuinely doesn't\ncover, and a working assistant tells you it doesn't know. That's not a failure case to\npatch around \u2014 it's the one honest answer to a question the document can't answer, and it's\nthe single most convincing thing you can show someone when you demo this. A confident wrong\nanswer is worse than an honest \"I don't know,\" every time."}),"\n",(0,o.jsx)(n.h2,{id:"whats-next",children:"What's next"}),"\n",(0,o.jsx)(n.p,{children:"You now have the full picture: what you're building, why each piece is in it, and which\nlabs \u2014 not new material \u2014 supplied every piece. The lab is where you actually wire it\ntogether, run it, break it on purpose, and watch the honest failure happen live. Module 10\nis graduation: a recap of everything you've built, a final practice test, and the three\npaths \u2014 MLOps, LLMOps, and Agentic DevOps \u2014 that pick up from exactly where this assistant\nleaves off."})]})}function u(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},7684(e,n,t){t.d(n,{A:()=>a});var s=t(4848);t(6540);var o=t(6497);function a({src:e,title:n="Slides"}){let t=(0,o.Ay)(e);return(0,s.jsxs)("div",{className:"deck_nWXz",children:[(0,s.jsxs)("div",{className:"bar_dOoE",children:[(0,s.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",n]}),(0,s.jsx)("a",{className:"full_PrDQ",href:t,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,s.jsx)("div",{className:"frame_M4DO",children:(0,s.jsx)("iframe",{src:t,title:n,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,n,t){t.d(n,{R:()=>i,x:()=>r});var s=t(6540);let o={},a=s.createContext(o);function i(e){let n=s.useContext(a);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),s.createElement(a.Provider,{value:n},e.children)}}}]);